<template>
  <view class="dz-page booking-page confirm-page">
    <header class="booking-head confirm-head"><button aria-label="返回" @tap="goBack">‹</button><text>确认订单</text></header>
    <view v-if="draft" class="booking-content">
      <section class="provider-summary booking-card"><view class="booking-avatar"><image v-if="draft.providerAvatarUrl" :src="draft.providerAvatarUrl" mode="aspectFill" /><view v-else>{{ draft.providerName.slice(0,1) }}</view></view><view><view class="name-line"><strong>{{ draft.providerName }}</strong><text v-if="draft.providerVerified">⬟ 实名认证</text></view><text>{{ draft.serviceName }}</text><strong class="price">¥{{ money(draft.unitPrice) }}<small>{{ draft.billingType==='hourly'?'/小时':'/次' }}</small></strong></view><view class="brand-ticket">DAZZY<br/><b>搭子</b></view></section>
      <section class="order-info booking-card">
        <button @tap="edit('/pages/booking/time')"><i>◷</i><strong>服务时间</strong><text>{{ dateTimeLabel }}</text><b>›</b></button>
        <button @tap="edit('/pages/booking/location')"><i>●</i><view><strong>集合地点</strong><text>{{ draft.address }}</text></view><b>›</b></button>
        <button @tap="edit('/pages/booking/location')"><i>⌕</i><strong>联系方式</strong><text>{{ maskedPhone }}</text><b>›</b></button>
      </section>
      <section class="extras booking-card"><button><i>券</i><strong>优惠券</strong><text>{{ discountAmount ? `已优惠 −¥${discount}` : '暂无可用优惠券' }}</text><em>›</em></button><button @tap="editingNote=true"><i>✎</i><strong>备注</strong><text v-if="!draft.note">如有其他需求，请备注说明（选填）</text><text v-else>{{ draft.note }}</text><em>›</em></button><textarea v-if="editingNote" v-model="note" maxlength="120" placeholder="请填写出行、沟通等特殊需求" @blur="saveNote" /></section>
      <section class="fee-card booking-card"><text class="fee-title">费用明细</text><view><text>服务费</text><text>¥{{ serviceFee }}</text></view><view><text>往返交通费</text><text>¥{{ travelFee }}</text></view><view><text>优惠券</text><text class="discount">−¥{{ discount }}</text></view><view class="total"><text>合计</text><strong>¥{{ total }}</strong></view><text v-if="previewError" class="quote-error">{{ previewError }}</text></section>
      <label class="agreement" @tap="agreed=!agreed"><text :class="{active:agreed}">{{ agreed?'✓':'' }}</text>我已阅读并同意<em>服务规则</em></label>
    </view>
    <view v-else class="booking-empty">预约信息已失效，请返回达人详情重新选择。</view>
    <footer v-if="draft" class="booking-footer"><view class="booking-price">合计 <strong>¥{{ total }}</strong></view><button :disabled="!agreed||submitting||!quote" @tap="submit">{{ submitting?'创建中…':'确认支付' }}</button></footer>
  </view>
</template>

<script setup lang="ts">
import { computed, ref } from 'vue'; import { onShow } from '@dcloudio/uni-app'; import { bookingEndTime, getBookingDraft, updateBookingDraft } from '@/services/bookingDraft'; import type { BookingDraft } from '@/services/bookingDraft'; import { createProviderOrder, previewProviderOrder } from '@/services/orders'; import type { ProviderOrderQuote } from '@/types/api'; import { formatAmount, getErrorMessage } from '@/utils/formatters'
const draft=ref<BookingDraft|null>(null),quote=ref<ProviderOrderQuote|null>(null),agreed=ref(false),editingNote=ref(false),note=ref(''),submitting=ref(false),previewError=ref('')
const serviceFee=computed(()=>formatAmount(quote.value?.service_fee_amount||0)),travelFee=computed(()=>formatAmount(quote.value?.transport_fee_amount||0)),discountAmount=computed(()=>quote.value?.discount_amount||0),discount=computed(()=>formatAmount(discountAmount.value)),total=computed(()=>formatAmount(quote.value?.payable_amount||0))
const dateTimeLabel=computed(()=>{if(!draft.value)return'';const d=new Date(`${draft.value.date}T00:00:00`);return `${String(d.getMonth()+1).padStart(2,'0')}月${String(d.getDate()).padStart(2,'0')}日 ${draft.value.startTime}—${bookingEndTime(draft.value.startTime,draft.value.durationMinutes)}`})
const maskedPhone=computed(()=>draft.value?.contactPhone.replace(/^(\d{3})\d{4}(\d{4})$/,'$1****$2')||'')
const money=formatAmount
function goBack(){uni.navigateBack()}
function edit(url:string){uni.navigateTo({url})}
function saveNote(){updateBookingDraft({note:note.value.trim()});if(draft.value)draft.value.note=note.value.trim();editingNote.value=false}
async function refreshQuote(){if(!draft.value)return;previewError.value='';try{quote.value=(await previewProviderOrder(draft.value)).data}catch(reason){quote.value=null;previewError.value=getErrorMessage(reason,'订单金额获取失败')}}
async function submit(){if(!draft.value||!quote.value||submitting.value)return;submitting.value=true;try{const order=(await createProviderOrder(draft.value)).data;uni.navigateTo({url:`/pages/booking/payment?orderNo=${order.order_no}`})}catch(reason){uni.showToast({title:getErrorMessage(reason,'订单创建失败'),icon:'none'})}finally{submitting.value=false}}
onShow(()=>{draft.value=getBookingDraft();note.value=draft.value?.note||'';refreshQuote()})
</script>

<style lang="scss" scoped>
@use '../../styles/tokens.scss' as *; @use '../../styles/booking.scss';
.confirm-page{background:linear-gradient(180deg,#dffbfc 0,#f5f7f8 380rpx)}.confirm-head{background:transparent}.provider-summary{position:relative;display:flex;align-items:center;min-height:180rpx;padding:22rpx;overflow:hidden}.provider-summary .booking-avatar{width:116rpx;height:140rpx}.provider-summary>view:nth-child(2){display:flex;flex-direction:column;gap:12rpx;margin-left:22rpx}.name-line{display:flex;align-items:center;gap:12rpx}.name-line strong{font-size:32rpx}.name-line text{padding:4rpx 9rpx;border-radius:8rpx;color:$dz-brand-deep;background:$dz-brand-soft;font-size:17rpx}.provider-summary>view>text{color:$dz-text-secondary;font-size:21rpx}.price{color:$dz-price-primary;font-size:35rpx}.price small{color:$dz-text-primary;font-size:20rpx;font-weight:500}.brand-ticket{position:absolute;right:26rpx;top:28rpx;padding:14rpx 18rpx;border-radius:14rpx;color:#fff;background:$dz-gradient-brand;text-align:center;font-size:18rpx;transform:rotate(5deg)}.brand-ticket b{font-size:28rpx}.order-info,.extras{margin-top:18rpx;padding:0 20rpx}.order-info button,.extras button{display:flex;align-items:center;width:100%;min-height:92rpx;margin:0;padding:15rpx 0;border:0;border-bottom:1rpx solid $dz-border-subtle;background:#fff;text-align:left;line-height:1.35}.order-info button:last-child,.extras button:last-of-type{border-bottom:0}.order-info button::after,.extras button::after{display:none}.order-info i,.extras i{display:flex;align-items:center;justify-content:center;width:52rpx;height:52rpx;border-radius:50%;color:$dz-brand-deep;background:$dz-brand-soft;font-size:22rpx;font-style:normal}.order-info strong,.extras strong{margin-left:16rpx;font-size:23rpx}.order-info button>text,.order-info button>view,.extras button>text{flex:1;margin-left:20rpx;color:$dz-text-secondary;text-align:right;font-size:20rpx}.order-info button>view{display:flex;flex-direction:column;align-items:flex-start;text-align:left}.order-info button>view strong{margin:0;color:$dz-text-primary}.order-info button>view text{margin-top:8rpx;color:$dz-text-secondary;font-size:19rpx}.order-info button>b,.extras em{margin-left:10rpx;color:$dz-text-tertiary;font-size:34rpx;font-style:normal}.extras button>text b{color:$dz-price-primary;font-weight:500}.extras textarea{width:100%;height:120rpx;padding:15rpx;border:1rpx solid $dz-border-subtle;border-radius:14rpx;box-sizing:border-box;font-size:21rpx}.fee-card{margin-top:18rpx;padding:23rpx 24rpx}.fee-title{display:block;margin-bottom:18rpx;font-size:27rpx;font-weight:700}.fee-card>view{display:flex;justify-content:space-between;padding:10rpx 0;font-size:22rpx}.fee-card .discount{color:$dz-price-primary}.fee-card .total{margin-top:8rpx;padding-top:17rpx;border-top:1rpx dashed $dz-border-subtle;font-size:25rpx}.total strong{color:$dz-price-primary;font-size:34rpx}.agreement{display:flex;align-items:center;margin:24rpx 5rpx;color:$dz-text-secondary;font-size:19rpx}.agreement>text{display:flex;align-items:center;justify-content:center;width:30rpx;height:30rpx;margin-right:10rpx;border:2rpx solid #b8c0c3;border-radius:50%;color:#fff}.agreement>text.active{border-color:$dz-brand-primary;background:$dz-brand-primary}.agreement em{color:$dz-brand-deep;font-style:normal}.booking-footer .booking-price{display:flex;align-items:center;gap:10rpx;color:$dz-text-primary;font-size:25rpx}.booking-footer .booking-price strong{margin:0;font-size:37rpx}
.quote-error{display:block;margin-top:14rpx;color:$dz-price-primary;font-size:19rpx}
</style>
